SELECT 'gongkao', '查数定位', 'kp-xingce-data-calc-locate', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "查数定位"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "资料分析的第一步，精准匹配题干要素与材料数据的过程。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "所有资料分析题目的前置动作。只要题目给出了时间、主体、指标，就需要你回原文中找到对应的数值。特征是没有明显的计算提示，或作为计算的第一步。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推论"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "找错数 = 100% 错题。材料往往会通过“时间倒错”、“主体嵌套”、“近义词替换”来布设找数陷阱。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读题干拆解三要素] --> B[圈定时间:现期/基期?]\nB --> C[圈定主体:全国/某省? 总体/部分?]\nC --> D[圈定指标:量/率/比重?]\nD --> E{材料类型}\nE -- 图表 --> F[直奔表头/图例/行列标题定位]\nE -- 文字 --> G[按段落首句寻找关键词]\nF --> H[最终核对表头单位!]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 2023年，我国新能源汽车产量为 958.7 万辆。问：2023年我国汽车总产量是多少？（材料另有一句：2023年汽车总产量 3016.1 万辆，其中新能源汽车 958.7 万辆）"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "拆解题干：时间=2023年，主体=汽车总产量，指标=绝对量（万辆）。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "回文定位：在文字材料中寻找“2023年”、“汽车总产量”。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "规避干扰：不要被题目中的“新能源汽车 958.7 万辆”带偏，题干求的是“总产量”。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "锁定数据：精确提取数据“3016.1 万辆”。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "偷换主体与遗漏单位：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "材料给的是“规上工业企业增加值”，题目问的是“工业增加值”。两者绝对不等同！找完数后，往上看一眼单位，是“万元”还是“亿元”，这决定了你需不需要加减几个零！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "每次做套卷，给自己规定前两道纯找数题必须在 30 秒内选出答案，强制自己圈划题干和材料的关键词，形成“指哪打哪”的肌肉记忆。"}]}]}$$ AS jsonb), NULL, '查数定位的核心考点与实战推导。', category_node.id, CAST('["资料分析", "查数定位"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_calc_locate", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
